import{_ as a,o as e,c as r,a0 as s}from"./chunks/framework.DqMqoJl9.js";const g=JSON.parse('{"title":"关于 Cherry","description":"","frontmatter":{},"headers":[],"relativePath":"guides/cherry.md","filePath":"guides/cherry.md"}'),i={name:"guides/cherry.md"};function h(d,t,o,l,n,c){return e(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="关于-cherry" tabindex="-1">关于 Cherry <a class="header-anchor" href="#关于-cherry" aria-label="Permalink to &quot;关于 Cherry&quot;">​</a></h1><p>Cherry 是一款用 Go 语言实现的游戏服务端框架，具有高性能、可伸缩、分布式的特点。它帮你省去搭建业务框架的工作——不用重复造轮子，把精力放在游戏逻辑本身。</p><p>框架基于 <strong>NATS</strong> 进行消息分发，依托 <strong>Goroutine</strong> 的优势实现 <strong>Actor 模型</strong>，按业务需要可以构建成千上万个 Actor 实例，方便玩家与玩家之间、模块与模块之间通信。</p><h2 id="核心思路" tabindex="-1">核心思路 <a class="header-anchor" href="#核心思路" aria-label="Permalink to &quot;核心思路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td><a href="/core/actor-model.html">Actor 模型</a></td><td>每个 Actor 独占一个 goroutine 串行处理消息，Actor 内部状态无需加锁</td></tr><tr><td><a href="/core/component.html">组件管理</a></td><td>用组件组合功能，框架统一管理生命周期，按需注册</td></tr><tr><td><a href="/core/cluster.html">通信 &amp; 集群</a></td><td>节点间基于 NATS 通信，支持本地配置 / NATS 主从 / etcd 三种发现方式</td></tr><tr><td><a href="/core/connector.html">连接器</a></td><td>组件化的网络连接器，自带 TCP、WebSocket</td></tr><tr><td><a href="/core/net-packet.html">网络数据包</a></td><td>内置 Pomelo 与 Simple 两种协议，序列化支持 JSON / Protobuf</td></tr><tr><td><a href="/core/profile.html">Profile 配置</a></td><td>一份 JSON 配置管理所有参数，支持多环境与文件拆分</td></tr></tbody></table><h2 id="两个模式" tabindex="-1">两个模式 <a class="header-anchor" href="#两个模式" aria-label="Permalink to &quot;两个模式&quot;">​</a></h2><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 单机模式：单进程开发调试，不需要任何外部服务</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cherry.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;room-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, cherry.Standalone)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 集群模式：多进程多节点，需要 NATS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cherry.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, cherry.Cluster)</span></span></code></pre></div><p>单机模式适合开发期；集群模式下框架会自动注册集群组件与发现服务组件，节点之间通过 NATS 互相通信、互相发现，服务可以横向扩展。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>依赖</th><th>版本</th><th>何时需要</th></tr></thead><tbody><tr><td>Go</td><td>&gt;= 1.24</td><td>必需</td></tr><tr><td>NATS</td><td>&gt;= 2.0</td><td>集群模式、<code>demo_cluster</code>、<code>test_discovery</code></td></tr><tr><td>MySQL</td><td>—</td><td>使用 <a href="/core/gorm.html">gorm 组件</a> 时</td></tr><tr><td>Redis</td><td>—</td><td><a href="/core/data-config.html">data-config</a> 用 Redis 做数据源时</td></tr><tr><td>MongoDB</td><td>—</td><td>使用 <a href="/core/mongo.html">mongo 组件</a> 时</td></tr><tr><td>etcd</td><td>v3</td><td>使用 <a href="/core/etcd.html">etcd 组件</a> 做发现服务时</td></tr></tbody></table><h2 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h2><p>当前框架版本 <strong>v1.6.8</strong>，组件版本 <strong>v1.5.0</strong>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>先看整体结构：<a href="/guides/architecture.html">架构总览</a></li><li>新项目从零开始：<a href="/guides/code-cherry.html">编写一个 Cherry 服务器</a></li><li>先跑起来看效果：<a href="/examples/demo-chat.html">单节点聊天室</a></li><li>了解完整项目结构：<a href="/examples/demo-cluster.html">多节点集群</a></li><li>从旧版本升级：<a href="/advanced/migration.html">版本迁移指南</a></li></ul><h2 id="相关仓库" tabindex="-1">相关仓库 <a class="header-anchor" href="#相关仓库" aria-label="Permalink to &quot;相关仓库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>仓库</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://github.com/cherry-game/cherry" target="_blank" rel="noreferrer">cherry</a></td><td>框架核心</td></tr><tr><td><a href="https://github.com/cherry-game/components" target="_blank" rel="noreferrer">components</a></td><td>官方组件（cron / gin / gorm / mongo / gops / etcd / data-config）</td></tr><tr><td><a href="https://github.com/cherry-game/examples" target="_blank" rel="noreferrer">examples</a></td><td>示例与测试工程</td></tr><tr><td><a href="https://github.com/cherry-game/cherry-docs" target="_blank" rel="noreferrer">cherry-docs</a></td><td>本站文档源码</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">模块路径</p><p>组件已从主仓库迁出，import 路径为 <code>github.com/cherry-game/components/&lt;组件名&gt;</code>，<strong>没有</strong> <code>cherry/</code> 这一段。旧路径 <code>github.com/cherry-game/cherry/components/...</code> 已废弃。</p></div>`,17)])])}const k=a(i,[["render",h]]);export{g as __pageData,k as default};
